#include <stdio.h>
/* ex08：RAID 0/1/5/6/10 的容量、可靠性与读写特性
 * 用 n 块 disk_size 的盘，算可用容量与「容忍几块盘坏」。*/
typedef struct {
    const char *name;
    int data_disks;     /* 承载数据的盘数 */
    int parity_disks;   /* 校验盘数（含镜像副本） */
    int tolerate;       /* 可容忍同时坏几块 */
    const char *note;
} Raid;

int main(void) {
    int n = 6;
    double d = 4.0;     /* 每块 4TB */
    Raid r[] = {
        {"RAID 0 条带",   6, 0, 0, "容量 100%，无冗余，坏一块全崩"},
        {"RAID 1 镜像",   3, 3, 1, "容量 50%，每组镜像各坏一块仍可用"},
        {"RAID 5 校验",   5, 1, 1, "容量 (n-1)/n，单盘校验"},
        {"RAID 6 双校验", 4, 2, 2, "容量 (n-2)/n，可容忍双盘故障"},
        {"RAID 10 镜像+条带", 3, 3, 1, "容量 50%，重建快但成本高"}
    };
    int m = (int)(sizeof(r) / sizeof(r[0]));

    printf("%d 块 %0.0fTB 盘，各 RAID 级别对比\n", n, d);
    printf("--------------------------------------------------------------------------\n");
    printf("%-18s %-14s %-12s %s\n", "级别", "可用容量(TB)", "容忍坏盘", "说明");
    for (int i = 0; i < m; i++) {
        double cap = r[i].data_disks * d;
        printf("%-18s %-14.1f %-12d %s\n", r[i].name, cap, r[i].tolerate, r[i].note);
    }
    printf("--------------------------------------------------------------------------\n");
    printf("结论：RAID 不是备份——它防「盘坏」，不防「误删/勒索/机房火灾」。\n");
    printf("      RAID 5 的写惩罚：一次随机写要读旧数据+旧校验、写新数据+新校验 = 4 次 I/O；\n");
    printf("      故写密集型场景更偏好 RAID 10，读密集/容量敏感偏好 RAID 5/6。\n");
    return 0;
}
